// Join Surfline's wave + wind series on timestamp and flag which intervals are firing.
const cfg     = $('Config').first().json;
const waveRes = $('Surfline wave').first().json ?? {};
const wave    = waveRes.data?.wave ?? [];
const wind    = $('Surfline wind').first().json?.data?.wind ?? [];

if (!wave.length) throw new Error('Surfline returned no wave data - check the spotId in Config');

const windAt  = new Map(wind.map((w) => [w.timestamp, w]));
const COMPASS = ['N','NNE','NE','ENE','E','ESE','SE','SSE','S','SSW','SW','WSW','W','WNW','NW','NNW'];
const compass = (deg) => COMPASS[Math.round((deg ?? 0) / 22.5) % 16];

// Surfline timestamps are UTC seconds. Shift to the spot's local day before bucketing,
// or a swell that starts Friday evening in Bali lands on Thursday in your groupings.
// The response carries the spot's own offset, so changing spotId moves the timezone
// with it - the Config value is only a fallback.
const tzHours  = waveRes.associated?.utcOffset ?? cfg.tzOffsetHours;
const localDay = (ts) => new Date((ts + tzHours * 3600) * 1000).toISOString().slice(0, 10);

return wave.map((w) => {
  const wnd      = windAt.get(w.timestamp) ?? {};
  const swell    = w.swells.reduce((a, b) => (b.height > a.height ? b : a));
  const offshore = wnd.directionType === 'Offshore';

  return { json: {
    ts: w.timestamp,
    day: localDay(w.timestamp),
    surfMin: w.surf.min,
    surfMax: w.surf.max,
    humanRelation: w.surf.humanRelation,
    swellHeightM: swell.height,
    swellPeriodS: swell.period,
    swellDir: compass(swell.direction),
    windKts: Math.round(wnd.speed ?? 0),
    windDir: compass(wnd.direction),
    windType: wnd.directionType ?? 'unknown',
    offshore,
    firing: w.surf.max >= cfg.minSurfFt && offshore,
  } };
});

// Is this a swell EVENT? Needs minFiringDays *consecutive* local days that each
// contain at least one firing interval.
const cfg  = $('Config').first().json;
const rows = $input.all().map((i) => i.json);

const byDay = new Map();
for (const r of rows) {
  const d = byDay.get(r.day) ?? { day: r.day, firing: false, best: null };
  if (r.firing && (!d.best || r.surfMax > d.best.surfMax)) d.best = r;
  d.firing = d.firing || r.firing;
  byDay.set(r.day, d);
}
const days = [...byDay.values()].sort((a, b) => a.day.localeCompare(b.day));

const nextDay = (iso) => {
  const d = new Date(iso + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + 1);
  return d.toISOString().slice(0, 10);
};

// Longest run of CONSECUTIVE firing days. Counting scattered days (Mon + Wed + Fri)
// as a "3 day swell" is the easy mistake here - you'd fly in for a flat Tuesday.
let best = [], run = [];
for (const d of days) {
  const contiguous = run.length && nextDay(run[run.length - 1].day) === d.day;
  run = d.firing ? (contiguous ? [...run, d] : [d]) : [];
  if (run.length > best.length) best = run;
}

const swellOn    = best.length >= cfg.minFiringDays;
const departDate = best.length ? best[0].day : null;
const returnDate = best.length ? nextDay(best[best.length - 1].day) : null;

// Peak conditions come from FIRING intervals only. Take the max over all rows and you
// can end up announcing "offshore and clean" using the wind from an onshore hour.
const firing = rows.filter((r) => r.firing);
const peak   = firing.length ? firing.reduce((a, b) => (b.surfMax > a.surfMax ? b : a)) : null;

const forecastLines = best.filter((d) => d.best).map((d) =>
  `${d.day}   ${d.best.surfMin}-${d.best.surfMax}ft   ` +
  `${d.best.swellHeightM.toFixed(1)}m @ ${d.best.swellPeriodS}s ${d.best.swellDir}   ` +
  `${d.best.windKts}kt ${d.best.windDir}`
).join('\n');

return [{ json: {
  swellOn,
  // Stable id for this swell: every 6h run that sees the same swell computes the same
  // key, which is what makes the dedupe downstream work.
  eventKey: swellOn ? `${cfg.spotId}:${departDate}` : null,
  spotName: cfg.spotName,
  departDate,
  returnDate,
  firingDays: best.length,
  peakSurf:  peak ? `${peak.surfMin}-${peak.surfMax}ft` : null,
  peakHuman: peak?.humanRelation ?? null,
  peakWind:  peak ? `${peak.windKts}kt ${peak.windDir}` : null,
  forecastLines,
} }];

// Dedupe. Without this a 3 day swell satisfies the condition on ~12 consecutive
// 6-hourly runs, so you'd propose - and pay for - the same trip 12 times.
//
// CAVEAT: n8n only persists static data on PRODUCTION runs (workflow active, fired by
// its real trigger). Manual test executions always look "new". That's n8n, not this code.
const s     = $json;
const store = $getWorkflowStaticData('global');
store.claims = store.claims ?? {};

const THIRTY_DAYS = 30 * 24 * 3600 * 1000;
const now = Date.now();
for (const [key, claim] of Object.entries(store.claims)) {
  if (now - Date.parse(claim.claimedAt) > THIRTY_DAYS) delete store.claims[key];
}

const alreadyProposed = Boolean(store.claims[s.eventKey]);

// Claim BEFORE spending anything. Losing one proposal to a flaky API is cheap;
// double-charging the flight search and spamming the group chat is not.
if (!alreadyProposed) store.claims[s.eventKey] = { claimedAt: new Date().toISOString() };

return [{ json: { ...s, alreadyProposed } }];

// Amadeus flight-offers -> the 3 cheapest. The search node is set to continue on error,
// so "no fares" is a normal outcome here: the proposal still goes out, just without prices.
const cfg      = $('Config').first().json;
const res      = $input.first().json ?? {};
const offers   = Array.isArray(res.data) ? res.data : [];
const carriers = res.dictionaries?.carriers ?? {};

const priced = offers.map((o) => {
  const segs = o.itineraries?.[0]?.segments ?? [];
  const code = o.validatingAirlineCodes?.[0] ?? segs[0]?.carrierCode;
  return {
    price: Number(o.price?.grandTotal ?? o.price?.total),
    currency: o.price?.currency ?? cfg.currency,
    airline: carriers[code] ?? code ?? 'unknown',
    stops: Math.max(segs.length - 1, 0),
    departsAt: segs[0]?.departure?.at ?? null,
  };
})
.filter((o) => Number.isFinite(o.price))
.sort((a, b) => a.price - b.price)
.slice(0, 3);

const top = priced[0];
const flightLine = top
  ? `from ${top.currency} ${Math.round(top.price)} return, ${top.airline}` +
    (top.stops ? `, ${top.stops} stop` : ', direct')
  : 'live fares unavailable right now - check manually';

return [{ json: { flightsFound: priced.length, flightLine, options: priced } }];

const s = $('Evaluate swell').first().json;
const c = $('Config').first().json;
const f = $input.first().json;

const proposal = [
  `${s.spotName} is about to fire.`,
  '',
  `Surf     up to ${s.peakSurf}${s.peakHuman ? ` (${s.peakHuman})` : ''}`,
  `Wind     ${s.peakWind}, offshore`,
  `Window   ${s.firingDays} days straight, ${s.departDate} to ${s.returnDate}`,
  '',
  s.forecastLines,
  '',
  `Flights ${c.originIata} to ${c.destIata}: ${f.flightLine}`,
  '',
  'Say yes and I will send the booking links round.',
].join('\n');

return [{ json: { proposal } }];

// Rebuild the trip context for the executor. The approval node's own output is only
// { data: { approved, respondedAt } }, so pull the real detail back off the earlier nodes.
const s = $('Evaluate swell').first().json;
const f = $('Pick cheapest flights').first().json;
const c = $('Config').first().json;

return [{ json: {
  eventKey: s.eventKey,
  spotName: s.spotName,
  departDate: s.departDate,
  returnDate: s.returnDate,
  firingDays: s.firingDays,
  peakSurf: s.peakSurf,
  forecastLines: s.forecastLines,
  origin: c.originIata,
  destination: c.destIata,
  stayNear: c.stayNear,
  adults: c.adults,
  currency: c.currency,
  telegramChatId: c.telegramChatId,
  flights: f.options,
  flightLine: f.flightLine,
  approvedAt: $json.data?.respondedAt ?? null,
} }];

// Declined, or the approval window expired. The eventKey stays claimed, so this
// particular swell will not be proposed again - no nagging every 6 hours.
const s = $('Evaluate swell').first().json;
return [{ json: {
  outcome: 'not this time',
  eventKey: s.eventKey,
  spot: s.spotName,
  window: `${s.departDate} to ${s.returnDate}`,
  respondedAt: $json.data?.respondedAt ?? null,
} }];
